#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <inttypes.h>

void kissat_restarting(kissat *solver) {
    assert(solver->unassigned);
    if (!GET_OPTION(restart) || !solver->level || CONFLICTS < solver->limits.restart.conflicts)
        return;

    // Step 1: Maintain circular buffer of average LBD and conflict rate
    static double lbd_history[10] = {0};
    static double rate_history[10] = {0};
    static int history_idx = 0;
    static int history_count = 0;
    const int N = 10;

    double current_lbd = AVERAGE(fast_glue);
    double current_rate = (solver->mab_decisions > 0) ? (double)solver->mab_conflicts / solver->mab_decisions : 0;

    lbd_history[history_idx] = current_lbd;
    rate_history[history_idx] = current_rate;
    history_idx = (history_idx + 1) % N;
    if (history_count < N) history_count++;

    // Step 2: Compute average Quality Q
    unsigned stable_restarts = 0;
    for (unsigned i = 0; i < solver->mab_heuristics; i++) {
        stable_restarts += solver->mab_select[i];
    }

    // Default to current heuristic if not enough data
    unsigned next_heuristic = solver->heuristic;
    if (stable_restarts < solver->mab_heuristics) {
        next_heuristic = (solver->heuristic + 1) % solver->mab_heuristics;
        solver->mab_select[next_heuristic]++;
        return;
    }

    // Step 3: Calculate slope S of LBD history
    double S = 0.0;
    if (history_count >= 2) {
        double sum_x = 0, sum_y = 0, sum_xy = 0, sum_xx = 0;
        for (int i = 0; i < history_count; i++) {
            int idx = (history_idx - history_count + i + N) % N;
            double x = (double)i;
            double y = lbd_history[idx];
            sum_x += x;
            sum_y += y;
            sum_xy += x * y;
            sum_xx += x * x;
        }
        double n = (double)history_count;
        double denom = n * sum_xx - sum_x * sum_x;
        if (denom != 0) {
            S = (n * sum_xy - sum_x * sum_y) / denom;
        }
    }

    // Step 4: Calculate normalized std dev V of conflict rate history
    double V = 0.0;
    if (history_count >= 2) {
        double mean = 0.0;
        for (int i = 0; i < history_count; i++) {
            mean += rate_history[i];
        }
        mean /= history_count;

        double sum_sq_diff = 0.0;
        for (int i = 0; i < history_count; i++) {
            double diff = rate_history[i] - mean;
            sum_sq_diff += diff * diff;
        }

        if (mean > 1e-9) {
            double variance = sum_sq_diff / history_count;
            V = sqrt(variance) / mean;
        }
    }

    // Step 5: Momentum Override
    if (S < -0.1) {
        next_heuristic = solver->heuristic; // Performance improving
    } else if (S > 0.1) {
        next_heuristic = (solver->heuristic + 1) % solver->mab_heuristics; // Performance degrading
    } else {
        // Step 6: Adaptive Boltzmann Selection
        double T = 0.1 + V;
        double Q[2] = {0.0, 0.0};
        double max_exponent = -1e9;

        for (unsigned i = 0; i < solver->mab_heuristics; i++) {
            if (solver->mab_select[i] > 0) {
                Q[i] = solver->mab_reward[i] / solver->mab_select[i];
            } else {
                Q[i] = 0.0;
            }
            if (Q[i] / T > max_exponent) max_exponent = Q[i] / T;
        }

        double exp_val[2] = {0.0, 0.0};
        double sum_exp = 0.0;

        for (unsigned i = 0; i < solver->mab_heuristics; i++) {
            exp_val[i] = exp(Q[i] / T - max_exponent);
            sum_exp += exp_val[i];
        }

        if (sum_exp > 0) {
            double r = kissat_pick_double(&solver->random);
            double cumulative = 0.0;
            for (unsigned i = 0; i < solver->mab_heuristics; i++) {
                cumulative += exp_val[i] / sum_exp;
                if (r < cumulative) {
                    next_heuristic = i;
                    break;
                }
            }
        }
    }

    // Update heuristic selection
    solver->heuristic = next_heuristic;
    solver->mab_select[solver->heuristic]++;
}

