void kissat_restarting(kissat *solver) {
    // Step 1: Calculate raw performance metric 'P'
    const double average_lbd = AVERAGE(fast_glue);
    const double average_trail_level = AVERAGE(level);
    const double p_metric = 10000.0 / (average_lbd * sqrt(average_trail_level) + 1.0);

    // Step 2: Update exponential moving averages
    static double fast_ema[2] = {0};
    static double slow_ema[2] = {0};
    static unsigned stagnation_counter = 0;
    static bool initialized[2] = {false};

    const unsigned active = solver->heuristic;
    if (active < 2) {
        if (!initialized[active]) {
            fast_ema[active] = p_metric;
            slow_ema[active] = p_metric;
            initialized[active] = true;
        } else {
            fast_ema[active] += 0.3 * (p_metric - fast_ema[active]);
            slow_ema[active] += 0.05 * (p_metric - slow_ema[active]);
        }
    }

    // Step 3: Update Stagnation Counter
    uint64_t current_binary = GET(clauses_binary);
    static uint64_t last_binary = 0;
    uint64_t delta_binary = (current_binary >= last_binary) ? (current_binary - last_binary) : current_binary;
    last_binary = current_binary;

    stagnation_counter = (delta_binary == 0) ? stagnation_counter + 1 : 0;

    // Step 4: Calculate Priority P for each available mode
    double P[2] = {0};
    for (unsigned i = 0; i < solver->mab_heuristics && i < 2; i++) {
        if (initialized[i]) {
            P[i] = slow_ema[i] + 1.5 * (fast_ema[i] - slow_ema[i]) + 0.5 * p_metric;
        }
    }

    // Step 5: Apply Penalty if stagnation exceeds threshold
    if (stagnation_counter > 6) {
        if (active < 2) {
            P[active] *= 0.5;
        }
    }

    // Step 6: Select the next restart mode
    unsigned best_heuristic = active;
    double max_p = -1e100; // Initialize to a very low value

    for (unsigned i = 0; i < solver->mab_heuristics && i < 2; i++) {
        if (P[i] > max_p) {
            max_p = P[i];
            best_heuristic = i;
        }
    }

    solver->heuristic = best_heuristic;
    if (best_heuristic < 2) {
        solver->mab_select[best_heuristic]++;
    }

    // Reset counters for the next interval
    solver->mab_decisions = 0;
    solver->mab_conflicts = 0;
    solver->mab_chosen_tot = 0;
    for (all_variables(idx)) {
        solver->mab_chosen[idx] = 0;
    }
}

