void kissat_restarting(kissat *solver) {
    // Static state for managing EMAs and performance metrics
    static double fast_ema[2] = {0.0, 0.0};
    static double slow_ema[2] = {0.0, 0.0};
    static unsigned stagnation_counter = 0;
    static bool initialized = false;
    static unsigned last_mode = 0;

    // Ensure we have valid heuristics
    if (solver->mab_heuristics > 2) return;

    // Step 1: Calculate yield Y
    double sum_of_lbd = AVERAGE(fast_glue);
    double yield = (double)solver->mab_conflicts / (sum_of_lbd > 0 ? sum_of_lbd : 1);

    // Initialize EMAs on first run
    if (!initialized) {
        fast_ema[0] = yield;
        slow_ema[0] = yield;
        fast_ema[1] = yield;
        slow_ema[1] = yield;
        initialized = true;
    }

    // Step 2: Update EMAs for the current mode
    unsigned current_mode = solver->heuristic;
    fast_ema[current_mode] = 0.8 * fast_ema[current_mode] + 0.2 * yield;
    slow_ema[current_mode] = 0.95 * slow_ema[current_mode] + 0.05 * yield;

    // Step 3: Calculate momentum M
    double momentum[2];
    for (unsigned i = 0; i < 2; i++) {
        momentum[i] = fast_ema[i] - slow_ema[i];
    }

    // Step 4: Compute projected score P
    double projected[2];
    for (unsigned i = 0; i < 2; i++) {
        projected[i] = fast_ema[i] + (1.5 * momentum[i]);
    }

    // Step 5: Track stagnation counter
    uint64_t new_glue_clauses = GET(clauses_binary);
    if (new_glue_clauses == 0) {
        stagnation_counter++;
    } else {
        stagnation_counter = 0;
    }

    // Step 6: Apply penalty if stagnation exceeds threshold
    if (stagnation_counter > 6) {
        projected[current_mode] *= 0.5;
    }

    // Step 7: Select the mode with the highest projected score
    unsigned best_mode = current_mode;
    for (unsigned i = 0; i < 2; i++) {
        if (projected[i] > projected[best_mode]) {
            best_mode = i;
        }
    }

    // Update the solver's heuristic
    solver->heuristic = best_mode;

    // Update selection statistics
    if (best_mode < solver->mab_heuristics) {
        solver->mab_select[best_mode]++;
    }

    // Reset MAB counters for the next interval
    solver->mab_conflicts = 0;
    solver->mab_decisions = 0;
    solver->mab_chosen_tot = 0;
    for (all_variables(idx)) {
        solver->mab_chosen[idx] = 0;
    }
}

