    assert(solver->unassigned);
    if (!GET_OPTION(restart) || !solver->level)
        return false;
    if (CONFLICTS < solver->limits.restart.conflicts)
        return false;

    // Step 1: Maintain circular buffer for LBD and conflict rate
    static double lbd_history[10] = {0};
    static double conflict_rate_history[10] = {0};
    static int history_index = 0;
    static int history_count = 0;
    const int N = 10;

    double current_lbd = AVERAGE(fast_glue);
    double current_conflict_rate = (solver->mab_decisions > 0) ?
        (double)solver->mab_conflicts / solver->mab_decisions : 0.0;

    lbd_history[history_index] = current_lbd;
    conflict_rate_history[history_index] = current_conflict_rate;
    history_index = (history_index + 1) % N;
    if (history_count < N) history_count++;

    // Step 2: Calculate linear regression slope S
    double S = 0.0;
    if (history_count >= 2) {
        double sum_x = 0, sum_y = 0, sum_xy = 0, sum_xx = 0;
        for (int i = 0; i < history_count; i++) {
            int idx = (history_index - history_count + i + N) % N;
            double x = (double)i;
            double y = lbd_history[idx];
            sum_x += x;
            sum_y += y;
            sum_xy += x * y;
            sum_xx += x * x;
        }
        double n = (double)history_count;
        double denom = n * sum_xx - sum_x * sum_x;
        if (denom != 0) {
            S = (n * sum_xy - sum_x * sum_y) / denom;
        }
    }

    // Step 3: Calculate normalized standard deviation V of conflict rate
    double V = 0.0;
    if (history_count >= 2) {
        double mean = 0.0;
        for (int i = 0; i < history_count; i++) {
            mean += conflict_rate_history[i];
        }
        mean /= history_count;

        double sum_sq_diff = 0;
        for (int i = 0; i < history_count; i++) {
            double diff = conflict_rate_history[i] - mean;
            sum_sq_diff += diff * diff;
        }

        if (mean > 1e-9) {
            double variance = sum_sq_diff / history_count;
            V = sqrt(variance) / mean;
        }
    }

    // Step 4: Compute raw reward R
    uint64_t elapsed_ticks = solver->ticks;
    double R = (elapsed_ticks > 0) ?
        log2((double)solver->mab_conflicts + 1) / (elapsed_ticks + 1) : 0.0;

    // Step 5: Update Q-value
    static double Q[2] = {0.0, 0.0};
    double alpha = 0.2; // Dynamic adjustment can be added later
    unsigned mode = solver->heuristic;

    Q[mode] = (1 - alpha) * Q[mode] + alpha * (R + S);

    // Step 6: Calculate Selection Score S for both modes
    double S_current = Q[mode] * pow(0.95, solver->mab_select[mode]);
    double S_other = Q[1 - mode];

    // Step 7: Select the mode with the highest S
    if (S_other > S_current) {
        solver->heuristic = 1 - mode;
        solver->mab_select[solver->heuristic]++;
    } else {
        solver->mab_select[mode]++;
    }

    // Step 8: Adaptive Boltzmann Selection if stagnation detected
    if (fabs(S_current - S_other) <= 0.25) {
        double T = 0.1 + V;
        double exp_values[2] = {0.0, 0.0};
        double max_exponent = -1e9;
        for (unsigned i = 0; i < 2; i++) {
            if (solver->mab_select[i] > 0) {
                exp_values[i] = exp(Q[i] / T);
                if (exp_values[i] > max_exponent) max_exponent = exp_values[i];
            }
        }

        double sum_exp = exp_values[0] + exp_values[1];
        double r = kissat_pick_double(&solver->random);
        double cumulative = 0.0;

        for (unsigned i = 0; i < 2; i++) {
            cumulative += exp_values[i] / sum_exp;
            if (r < cumulative) {
                solver->heuristic = i;
                break;
            }
        }
    }

    // Reset MAB tracking fields for the next phase
    solver->mab_decisions = 0;
    solver->mab_conflicts = 0;

    return true;
}

