    static double fast_ema_lbd = 0.0;
    static double slow_ema_lbd = 0.0;
    static double fast_ema_rate = 0.0;
    static double slow_ema_rate = 0.0;

    const double alpha_fast_lbd = 0.15;
    const double alpha_slow_lbd = 0.05;
    const double alpha_fast_rate = 0.15;
    const double alpha_slow_rate = 0.05;

    fast_ema_lbd = alpha_fast_lbd * current_lbd + (1 - alpha_fast_lbd) * fast_ema_lbd;
    slow_ema_lbd = alpha_slow_lbd * current_lbd + (1 - alpha_slow_lbd) * slow_ema_lbd;
    fast_ema_rate = alpha_fast_rate * current_conflict_rate + (1 - alpha_fast_rate) * fast_ema_rate;
    slow_ema_rate = alpha_slow_rate * current_conflict_rate + (1 - alpha_slow_rate) * slow_ema_rate;

    // Step 3: Calculate linear regression slope S
    double S = 0.0;
    if (history_count >= 2) {
        double sum_x = 0, sum_y = 0, sum_xy = 0, sum_xx = 0;
        for (int i = 0; i < history_count; i++) {
            int idx = (history_index - history_count + i + 10) % 10;
            double x = i;
            double y = lbd_history[idx];
            sum_x += x;
            sum_y += y;
            sum_xy += x * y;
            sum_xx += x * x;
        }
        double n = (double)history_count;
        double denom = n * sum_xx - sum_x * sum_x;
        if (denom != 0) {
            S = (n * sum_xy - sum_x * sum_y) / denom;
        }
